 document.querySelector('#retry').onclick=()=>{state.dead=false;state.hp=state.maxHp;state.qi=state.maxQi;player.position.set(0,0,7);document.querySelector('#defeat').style.display='none';for(const e of enemies){e.visible=true;e.userData.alive=true;e.userData.hp=e.userData.max;e.userData.hpfg.scale.x=1}state.kills=0;state.shards=0;state.stage=1;for(const s of shrines){s.active=false;s.crystal.material=mats.jade}boss.visible=false;refresh()};
